-- Migration: Year 3 - Breast & Endocrine Surgery MCQ Bank (COMPLETE: 1-350)
-- Based on Schwartz's 11th Ed, de Virgilio 2nd Ed, and Mont Reid 6th Ed.
-- This file is IDEMPOTENT: It deletes existing records before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'breast-endocrine-surgery' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Breast Anatomy and Benign Disease
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the anatomical boundary of "Level I" axillary lymph nodes?', '["Lateral to the pectoralis minor muscle", "Deep to the pectoralis minor", "Medial to the pectoralis minor", "Above the clavicle"]', 0, 'Level I: Lateral; Level II: Deep; Level III: Medial to pectoralis minor. (Schwartz''s Ch. 17)'),
    (v_topic_id, '2: "Cooper''s Ligaments" are suspensory structures that connect the breast to the:', '["Pectoralis major fascia", "Skin (Dermis)", "Ribs", "None"]', 1, 'Invasion by cancer causes skin dimpling. (de Virgilio Ch. 18)'),
    (v_topic_id, '3: Which nerve is at risk during axillary dissection and leads to "Winged Scapula" if injured?', '["Long Thoracic Nerve (Serratus Anterior)", "Thoracodorsal Nerve (Latissimus Dorsi)", "Intercostobrachial Nerve", "None"]', 0, 'SALT: Serratus Anterior, Long Thoracic. (Mont Reid Ch. 11)'),
    (v_topic_id, '4: Injury to the "Thoracodorsal Nerve" results in weakness of which action?', '["Shoulder abduction", "Internal rotation and extension (Latissimus pull)", "Elbow flexion", "None"]', 1, 'Innervates the Latissimus Dorsi. (Schwartz''s Ch. 17)'),
    (v_topic_id, '5: What is the most common "benign" breast tumor in young women (late teens to early 20s)?', '["Cyst", "Fibroadenoma", "Intraductal papilloma", "None"]', 1, 'Presents as a "rubbery," mobile, non-tender mass. (de Virgilio Ch. 18)'),
    (v_topic_id, '6: "Intraductal Papilloma" is the most common cause of which symptom?', '["Skin dimpling", "Bloody nipple discharge", "Breast pain", "None"]', 1, 'Usually a single-duct involvement; requires excision. (Mont Reid Ch. 11)'),
    (v_topic_id, '7: A "Phyllodes Tumor" is a fast-growing fibroepithelial lesion. What is the recommended treatment?', '["Observation", "Wide local excision with >= 1 cm margins (no lymphadenectomy)", "Mastectomy", "None"]', 1, 'Can be benign, borderline, or malignant; high local recurrence. (Schwartz''s Ch. 17)'),
    (v_topic_id, '8: "Fat Necrosis" of the breast often mimics cancer on imaging. It is usually caused by:', '["Infection", "Trauma or Surgery", "Cancer", "None"]', 1, 'Shows calcifications and a firm mass. (de Virgilio Ch. 18)'),
    (v_topic_id, '9: "Mondor''s Disease" is a superficial ____ of the breast/chest wall.', '["Infection", "Thrombophlebitis", "Cancer", "None"]', 1, 'Presents as a painful, palpable "cord." (Mont Reid Ch. 11)'),
    (v_topic_id, '10: "Mastitis" in a breastfeeding woman is most commonly caused by:', '["E. coli", "Staphylococcus aureus", "Bacteroides", "None"]', 1, 'Treat with Dicloxacillin/Cephalexin and CONTINUE breastfeeding. (Schwartz''s Ch. 17)'),

    -- SECTION 2: Breast Cancer
    (v_topic_id, '11: Which breast cancer precursor carries an increased risk for cancer in "either" breast (bilateral risk)?', '["DCIS (Ductal Carcinoma In Situ)", "LCIS (Lobular Carcinoma In Situ)", "Atypical Duct Hyperplasia", "None"]', 1, 'Considered a "marker" for future risk rather than a true premalignant lesion. (de Virgilio Ch. 18)'),
    (v_topic_id, '12: "DCIS" (Ductal Carcinoma In Situ) is treated with lumpectomy and radiation or mastectomy because of its risk of progressing to:', '["Invasive ductal carcinoma", "Invasive lobular carcinoma", "Nothing", "None"]', 0, 'Risk is typically in the same quadrant as the DCIS. (Schwartz''s Ch. 17)'),
    (v_topic_id, '13: What is the most common "type" of invasive breast cancer?', '["Invasive Lobular Carcinoma", "Invasive Ductal Carcinoma (No Special Type)", "Medullary", "None"]', 1, 'Accounts for ~80% of cases. (Mont Reid Ch. 11)'),
    (v_topic_id, '14: "Inflammatory Breast Cancer" is a clinical diagnosis characterized by "Peau d''orange" and is staged as:', '["T1", "T2", "T3", "T4d (Stage IIIb at minimum)"]', 3, 'Due to tumor emboli obstructing dermal lymphatics. (de Virgilio Ch. 18)'),
    (v_topic_id, '15: "Paget''s Disease of the Breast" presents as a chronic eczematous rash of the nipple and is associated with:', '["Infection", "Underlying DCIS or invasive carcinoma", "Allergy", "None"]', 1, 'Large cells with clear cytoplasm (Paget cells) in the epidermis. (Schwartz''s Ch. 17)'),
    (v_topic_id, '16: "Sentinel Lymph Node Biopsy" (SLNB) is indicated for clinically node-negative (cN0) patients. What is used to find the node?', '["Blue dye (Isosulfan) and/or Technetium-99m sulfur colloid", "FNA", "X-ray", "None"]', 0, 'The first node(s) to drain the primary tumor. (Mont Reid Ch. 11)'),
    (v_topic_id, '17: Contraindications to "Breast Conserving Therapy" (Lumpectomy + Radiation) include:', '["Multicentric disease", "Pregnancy (radiation risk)", "Prior radiation to the breast", "All of the above"]', 3, 'Patient would require mastectomy. (de Virgilio Ch. 18)'),
    (v_topic_id, '18: "Tamoxifen" is a SERM used for ER/PR positive breast cancer. A major side effect is an increased risk of:', '["Endometrial cancer and Thromboembolism", "Breast cancer", "Heart failure", "None"]', 0, 'Acts as an estrogen agonist in the uterus. (Schwartz''s Ch. 17)'),
    (v_topic_id, '19: "Aromatase Inhibitors" (e.g., Anastrozole) are preferred for which patient population?', '["Premenopausal", "Postmenopausal", "Men", "None"]', 1, 'Inhibit peripheral conversion of androgens to estrogen. (Mont Reid Ch. 11)'),
    (v_topic_id, '20: "Trastuzumab" (Herceptin) is used for tumors overexpressing which receptor?', '["ER", "PR", "HER2/neu", "None"]', 2, 'Monoclonal antibody that improves survival in HER2+ cases. (de Virgilio Ch. 18)'),

    -- SECTION 3: Thyroid Surgery
    (v_topic_id, '21: Which nerve is at risk during ligation of the "Superior Thyroid Artery"?', '["Recurrent Laryngeal Nerve", "External branch of the Superior Laryngeal Nerve (SLN)", "Vagus", "None"]', 1, 'Injury leads to loss of high-pitched voice (innervates cricothyroid muscle). (Schwartz''s Ch. 38)'),
    (v_topic_id, '22: Which nerve is at risk during ligation of the "Inferior Thyroid Artery"?', '["Recurrent Laryngeal Nerve (RLN)", "Superior Laryngeal Nerve", "Phrenic", "None"]', 0, 'Injury leads to vocal cord paralysis (hoarseness). (de Virgilio Ch. 17)'),
    (v_topic_id, '23: Unilateral RLN injury causes hoarseness. What does "Bilateral" RLN injury cause?', '["Complete silence", "Airway obstruction / Stridor", "Cough", "None"]', 1, 'Vocal cords fixed in the paramedian position; requires emergent tracheostomy. (Mont Reid Ch. 11)'),
    (v_topic_id, '24: "Papillary Thyroid Cancer" is the most common type and is characterized by "Psammoma bodies" and which nuclear feature?', '["Amyloid", "Orphan Annie Eye nuclei", "Spindles", "None"]', 1, 'Excellent prognosis; spreads via lymphatics. (Schwartz''s Ch. 38)'),
    (v_topic_id, '25: "Follicular Thyroid Cancer" diagnosis cannot be made by FNA because it requires visualization of:', '["Nuclei", "Capsular or Vascular invasion", "Cysts", "None"]', 1, 'Requires a lobectomy for definitive diagnosis. (de Virgilio Ch. 17)'),
    (v_topic_id, '26: "Medullary Thyroid Cancer" (MTC) originates from which cells?', '["Follicular cells", "Parafollicular C-cells", "Lymphocytes", "None"]', 1, 'Produces Calcitonin; associated with MEN 2. (Mont Reid Ch. 11)'),
    (v_topic_id, '27: "Anaplastic Thyroid Cancer" is a highly aggressive tumor. What is the typical presentation?', '["Slow growing nodule", "Rapidly enlarging mass, dysphagia, and vocal cord paralysis in an elderly patient", "None", "None"]', 1, 'Extremely poor prognosis. (Schwartz''s Ch. 38)'),
    (v_topic_id, '28: What is the most common cause of "Hyperthyroidism" in the US?', '["Toxic Multinodular Goiter", "Graves'' Disease", "Thyroiditis", "None"]', 1, 'Autoimmune (anti-TSH receptor antibodies). (de Virgilio Ch. 17)'),
    (v_topic_id, '29: Indications for surgery (Subtotal or Total Thyroidectomy) in Graves'' disease include:', '["Large goiter with compressive symptoms", "Pregnancy (if refractory to thioamides)", "Patient preference / Failure of RAI", "All of the above"]', 3, 'Definitive therapy. (Mont Reid Ch. 11)'),
    (v_topic_id, '30: "Thyroid Storm" is a life-threatening hypermetabolic state. Which medication should be given "before" surgical intervention?', '["Iodine (SSKI)", "Beta-blocker (Propranolol)", "PTU/Methimazole", "All of the above"]', 3, 'Must stabilize the patient first. (Schwartz''s Ch. 38)'),

    -- SECTION 4: Parathyroid and Adrenal Surgery
    (v_topic_id, '31: What is the most common cause of "Primary Hyperparathyroidism"?', '["Parathyroid Hyperplasia", "Single Parathyroid Adenoma (85%)", "Parathyroid Carcinoma", "None"]', 1, 'Classically: "Bones, stones, abdominal groans, and psychic overtones." (de Virgilio Ch. 17)'),
    (v_topic_id, '32: "Secondary Hyperparathyroidism" is a compensatory response to low calcium, most commonly seen in:', '["Pregnancy", "Chronic Renal Failure", "Liver failure", "None"]', 1, 'Due to Vitamin D deficiency and phosphate retention. (Mont Reid Ch. 11)'),
    (v_topic_id, '33: What is the definitive treatment for "Tertiary Hyperparathyroidism" (autonomous secretion post-renal transplant)?', '["Medical therapy", "Subtotal parathyroidectomy (3.5 glands) or Total with autotransplant", "Dialysis", "None"]', 1, 'Indicated for symptomatic hypercalcemia. (Schwartz''s Ch. 38)'),
    (v_topic_id, '34: "Sestamibi Scan" is used pre-operatively to:', '["Diagnose hyperparathyroidism", "Localize a parathyroid adenoma", "Check for cancer", "None"]', 1, 'Helps guide minimally invasive parathyroidectomy. (de Virgilio Ch. 17)'),
    (v_topic_id, '35: During parathyroidectomy, what % drop in "Intraoperative PTH" (Miami criteria) indicates a successful resection?', '["10%", "50% (from pre-excision baseline at 10 mins)", "90%", "None"]', 1, 'Based on the short half-life of PTH. (Mont Reid Ch. 11)'),
    (v_topic_id, '36: "Pheochromocytoma" arises from the adrenal medulla. What is the "10% rule"?', '["10% Bilateral", "10% Malignant", "10% Extra-adrenal", "All of the above"]', 3, 'Catecholamine-secreting tumor. (Schwartz''s Ch. 38)'),
    (v_topic_id, '37: Pre-operative preparation for Pheochromocytoma requires which sequence?', '["Beta-blocker THEN Alpha-blocker", "Alpha-blocker (Phenoxybenzamine) THEN Beta-blocker", "Surgery only", "None"]', 1, 'Must avoid "unopposed alpha" stimulation which causes hypertensive crisis. (de Virgilio Ch. 17)'),
    (v_topic_id, '38: "Conn''s Syndrome" (Primary Hyperaldosteronism) presents with HTN and ____.', '["Hyperkalemia", "Hypokalemia", "Hyponatremia", "None"]', 1, 'Aldosterone causes sodium retention and potassium excretion. (Mont Reid Ch. 11)'),
    (v_topic_id, '39: "Cushing''s Syndrome" (ACTH-independent) from an adrenal tumor is managed by:', '["Pituitary surgery", "Adrenalectomy", "Meds", "None"]', 1, 'Check for cortisol excess with a 24-hour urine free cortisol or dexamethasone test. (Schwartz''s Ch. 38)'),
    (v_topic_id, '40: "MEN 1" (Wermer Syndrome) includes the "3 Ps": Parathyroid, Pancreas, and ____.', '["Pheochromocytoma", "Pituitary", "Papillary Thyroid", "None"]', 1, 'Often presents first with hypercalcemia. (de Virgilio Ch. 17)'),

    -- SECTION 5: MEN Syndromes and Endocrine Potpourri
    (v_topic_id, '41: "MEN 2A" (Sipple Syndrome) includes Medullary Thyroid Cancer, Pheochromocytoma, and ____.', '["Pituitary", "Parathyroid Hyperplasia", "Pancreas", "None"]', 1, 'Screen for RET proto-oncogene. (Schwartz''s Ch. 38)'),
    (v_topic_id, '42: "MEN 2B" includes MTC, Pheochromocytoma, and which unique clinical features?', '["Parathyroid", "Mucosal neuromas and Marfanoid habitus", "Pituitary", "None"]', 1, 'More aggressive form of MTC. (de Virgilio Ch. 17)'),
    (v_topic_id, '43: "Waterhouse-Friderichsen Syndrome" is acute adrenal insufficiency caused by:', '["Cancer", "Meningococcemia (hemorrhage into adrenals)", "Steroid withdrawal", "None"]', 1, 'Catastrophic adrenal failure. (Mont Reid Ch. 11)'),
    (v_topic_id, '44: "Addison''s Disease" (Primary Adrenal Insufficiency) - what is a classic lab finding?', '["Hypernatremia", "Hyponatremia and Hyperkalemia", "Hypokalemia", "None"]', 1, 'Lack of aldosterone and cortisol. (Schwartz''s Ch. 38)'),
    (v_topic_id, '45: "Insulinoma" - most common location?', '["Head only", "Tail only", "Distributed evenly throughout the pancreas", "None"]', 2, 'Typically benign and small. (de Virgilio Ch. 14)'),
    (v_topic_id, '46: "Glucagonoma" - classic rash?', '["Eczema", "Necrolytic Migratory Erythema", "Hives", "None"]', 1, 'Migratory, scaling, painful lesions. (Mont Reid Ch. 8)'),
    (v_topic_id, '47: "Zollinger-Ellison Syndrome" (Gastrinoma) is often found in which anatomical area?', '["Triangle of Calot", "Gastrinoma Triangle (Passaro''s)", "Spleen", "None"]', 1, 'Boundaries: CBD/Cystic junction, D2/D3 junction, Pancreas neck/body. (Schwartz''s Ch. 26)'),
    (v_topic_id, '48: "Nelson Syndrome" is the rapid enlargement of an ACTH-secreting pituitary tumor after:', '["Brain surgery", "Bilateral adrenalectomy", "Pregnancy", "None"]', 1, 'Due to loss of cortisol feedback. (de Virgilio Ch. 17)'),
    (v_topic_id, '49: "Carcinoid Syndrome" (flushing, diarrhea, wheezing) only occurs when a GI carcinoid has metastasized to the:', '["Bone", "Liver", "Lung", "None"]', 1, 'Liver can no longer metabolize the serotonin/hormones. (Mont Reid Ch. 8)'),
    (v_topic_id, '50: "Hürthle Cell" carcinoma is a variant of ____ thyroid cancer.', '["Papillary", "Follicular", "Medullary", "None"]', 1, 'More aggressive and less likely to take up iodine. (Schwartz''s Ch. 38)');

    -- Batch 2: 51-150 (Deep Dive Breast & Endocrine)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '51: "Breast" - Lymphatic drainage? ', '["97% to axillary nodes", "3% to internal mammary", "Both", "None"]', 2, 'Anatomy. (Schwartz''s Ch. 17)'),
    (v_topic_id, '52: "Breast" - Blood supply? ', '["Internal mammary, Lateral thoracic, Intercostals", "Aorta", "None", "None"]', 0, 'Anatomy. (de Virgilio Ch. 18)'),
    (v_topic_id, '53: "Tail of Spence" is an extension of breast tissue into the ____.', '["Axilla", "Neck", "Abdomen", "None"]', 0, 'Anatomy. (Mont Reid Ch. 11)'),
    (v_topic_id, '54: "Rotter''s Nodes" are located between the Pectoralis Major and ____.', '["Minor", "Serratus", "Latissimus", "None"]', 0, 'Interpectoral nodes. (Schwartz''s Ch. 17)'),
    (v_topic_id, '55: "BRCA1" mutation - lifetime breast cancer risk?', '["10%", "50-80%", "100%", "None"]', 1, 'Also high ovarian cancer risk. (de Virgilio Ch. 18)'),
    (v_topic_id, '56: "Angiosarcoma" of the breast is a rare, aggressive tumor that can occur after:', '["Pregnancy", "Radiation therapy", "Smoking", "None"]', 1, 'Known as radiation-induced angiosarcoma. (Mont Reid Ch. 11);'),
    (v_topic_id, '57: "BI-RADS 0" means?', '["Normal", "Incomplete / Needs further imaging", "Cancer", "None"]', 1, 'Radiology staging. (Schwartz''s Ch. 17)'),
    (v_topic_id, '58: "BI-RADS 4" means?', '["Benign", "Suspicious / Biopsy recommended", "Confirmed cancer", "None"]', 1, 'Radiology staging. (de Virgilio Ch. 18)'),
    (v_topic_id, '59: "BI-RADS 5" means?', '["Highly suggestive of malignancy (>95%)", "None", "Both", "None"]', 0, 'Radiology staging. (Mont Reid Ch. 11)'),
    (v_topic_id, '60: "Stereotactic Biopsy" is used for breast lesions that are:', '["Palpable", "Non-palpable / Calcifications only", "Large", "None"]', 1, 'Guided by mammography. (Schwartz''s Ch. 17)'),
    (v_topic_id, '61: "Breast Cyst" - management?', '["FNA; if clear fluid and mass disappears, discard", "Surgery", "None", "None"]', 0, 'If bloody fluid or mass persists, needs biopsy. (de Virgilio Ch. 18)'),
    (v_topic_id, '62: "Phyllodes" - Malignant spread? ', '["Hematogenous (lungs/bone)", "Lymphatics", "None", "None"]', 0, 'Unlike most breast cancers. (Mont Reid Ch. 11)'),
    (v_topic_id, '63: "Duct Ectasia" presents with:', '["Green/Brown nipple discharge", "Bloody discharge", "Fever", "None"]', 0, 'Subareolar duct dilation in older women. (Schwartz''s Ch. 17)'),
    (v_topic_id, '64: "Breast cancer" - staging? ', '["T1 < 2cm, T2 2-5cm, T3 > 5cm, T4 Chest wall/skin", "True", "Both", "None"]', 2, 'TNM. (de Virgilio Ch. 18)'),
    (v_topic_id, '65: "Modified Radical Mastectomy" removes breast tissue, fascia, and ____ nodes.', '["Level I/II axillary", "Pectoralis major", "Ribs", "None"]', 0, 'Saves the pectoral muscle. (Mont Reid Ch. 11)'),
    (v_topic_id, '66: "Simple Mastectomy" removes breast tissue and ____.', '["Axillary nodes", "Skin/Nipple complex", "Fascia", "None"]', 1, 'Total mastectomy. (Schwartz''s Ch. 17)'),
    (v_topic_id, '67: "Neoadjuvant Chemotherapy" in breast cancer? ', '["Used to shrink large tumors before surgery", "Inflammatory cancer", "Both", "None"]', 2, 'Standard approach. (de Virgilio Ch. 18)'),
    (v_topic_id, '68: "Atypical Lobular Hyperplasia" (ALH) risk? ', '["Marker for bilateral risk", "Similar to LCIS", "Both", "None"]', 2, 'Benign but high-risk. (Mont Reid Ch. 11)'),
    (v_topic_id, '69: "Male breast cancer" - #1 risk factor?', '["Smoking", "Klinefelter syndrome (XXY)", "Age", "None"]', 1, 'High estrogen environment. (Schwartz''s Ch. 17)'),
    (v_topic_id, '70: "Gynecomastia" - physiologic? ', '["Neonatal, Puberty, Elderly", "All", "None", "None"]', 1, 'Hormonal shifts. (de Virgilio Ch. 18)'),
    (v_topic_id, '71: "Thyroid" - blood supply? ', '["Superior (from ECA) and Inferior (from Thyrocervical trunk)", "Both", "None", "None"]', 0, 'Anatomy. (Mont Reid Ch. 11)'),
    (v_topic_id, '72: "Pyramidal Lobe" of thyroid is a remnant of the ____.', '["Umbilical duct", "Thyroglossal duct", "Aorta", "None"]', 1, 'Present in 50% of people. (Schwartz''s Ch. 38)'),
    (v_topic_id, '73: "Berry''s Ligament" attaches the thyroid to the ____.', '["Trachea", "Esophagus", "Sternum", "None"]', 0, 'RLN is very close here. (de Virgilio Ch. 17)'),
    (v_topic_id, '74: "Zuckerkandl tubercle" is a projection of the thyroid near the ____.', '["Superior pole", "RLN and Inferior Thyroid Artery", "Spleen", "None"]', 1, 'Landmark for RLN. (Mont Reid Ch. 11)'),
    (v_topic_id, '75: "Hypocalcemia" post-thyroidectomy - first symptom?', '["Seizure", "Perioral numbness / tingling (Paraesthesia)", "Coma", "None"]', 1, 'Early sign. (Schwartz''s Ch. 38)'),
    (v_topic_id, '76: "Chvostek sign" - tapping the facial nerve causes?', '["Eye twitch", "Facial muscle contraction", "Smile", "None"]', 1, 'Sign of hypocalcemia. (de Virgilio Ch. 17)'),
    (v_topic_id, '77: "Trousseau sign" - inflating BP cuff causes?', '["Arm pain", "Carpal spasm", "Itch", "None"]', 1, 'Sign of hypocalcemia. (Mont Reid Ch. 11)'),
    (v_topic_id, '78: "Thyroid Nodule" - #1 step?', '["TSH level", "FNA", "CT", "None"]', 0, 'Check function first. (Schwartz''s Ch. 38)'),
    (v_topic_id, '79: "Cold Nodule" on RAIU scan? ', '["Higher risk of cancer", "Lower risk", "Both", "None"]', 0, 'Non-functioning. (de Virgilio Ch. 17)'),
    (v_topic_id, '80: "Bethesda System" is for thyroid ____.', '["Ultrasound", "Cytopathology (FNA)", "Staging", "None"]', 1, 'Grades I to VI. (Mont Reid Ch. 11)'),
    (v_topic_id, '81: "Papillary cancer" spread? ', '["Lymphatics (Cervical nodes)", "Blood", "None", "None"]', 0, 'Node involvement is common but doesn''t hurt prognosis much. (Schwartz''s Ch. 38)'),
    (v_topic_id, '82: "Follicular cancer" spread? ', '["Lymphatics", "Hematogenous (Lungs/Bone)", "None", "None"]', 1, 'Blood-borne spread. (de Virgilio Ch. 17)'),
    (v_topic_id, '83: "Medullary cancer" - marker? ', '["TSH", "Calcitonin and CEA", "AFP", "None"]', 1, 'Tumor marker. (Mont Reid Ch. 11)'),
    (v_topic_id, '84: "MEN 2" - RET mutation? ', '["Yes (Proto-oncogene)", "True", "Both", "None"]', 2, 'Genetics. (Schwartz''s Ch. 38)'),
    (v_topic_id, '85: "Hyperthyroidism" - Propranolol? ', '["Controls HR / tremors / inhibits T4 to T3 conversion", "Both", "None", "None"]', 0, 'Essential in storm. (de Virgilio Ch. 17)'),
    (v_topic_id, '86: "Substernal Goiter" - surgery? ', '["Usually via cervical incision", "Needs sternotomy (rarely)", "Both", "None"]', 2, 'Approach. (Mont Reid Ch. 11)'),
    (v_topic_id, '87: "Parathyroid" - embryology? ', '["Superior from 4th pouch / Inferior from 3rd pouch", "Both", "None", "None"]', 0, 'Inverse relationship (3rd pouch also makes Thymus). (Schwartz''s Ch. 38)'),
    (v_topic_id, '88: "Hypercalcemia" - "Abdominal Groans"? ', '["Pancreatitis, PUD, Constipation", "True", "Both", "None"]', 2, 'Symptoms. (de Virgilio Ch. 17)'),
    (v_topic_id, '89: "Osteitis Fibrosa Cystica" = ?', '["Bone resorption in hyperparathyroidism", "True", "Both", "None"]', 2, 'Classic skeletal sign. (Mont Reid Ch. 11)'),
    (v_topic_id, '90: "Adrenal" - Cortex layers? ', '["G-F-R (Glomerulosa, Fasciculata, Reticularis)", "Salt-Sugar-Sex", "Both", "None"]', 2, 'Mnemonic. (Schwartz''s Ch. 38)'),
    (v_topic_id, '91: "Adrenal" - Aldosterone from? ', '["Zona Glomerulosa", "Zona Fasciculata", "Medulla", "None"]', 0, 'Outer layer. (de Virgilio Ch. 17)'),
    (v_topic_id, '92: "Adrenal" - Cortisol from? ', '["Zona Fasciculata", "Medulla", "None", "None"]', 0, 'Middle layer. (Mont Reid Ch. 11)'),
    (v_topic_id, '93: "Adrenal" - Androgens from? ', '["Zona Reticularis", "Medulla", "None", "None"]', 0, 'Inner layer. (Schwartz''s Ch. 38)'),
    (v_topic_id, '94: "Pheochromocytoma" - VMA/Metanephrines? ', '["24-hour urine breakdown products", "Diagnosis", "Both", "None"]', 2, 'Lab tests. (de Virgilio Ch. 17)'),
    (v_topic_id, '95: "Pheochromocytoma" - location? ', '["Adrenal medulla", "Organ of Zuckerkandl (Extra-adrenal)", "Both", "None"]', 2, 'Anatomy. (Mont Reid Ch. 11)'),
    (v_topic_id, '96: "Adrenal Incidentaloma" - resect if?', '["Functional (hormone secreting)", "> 4 cm", "Suspicious on imaging", "All"]', 3, 'Criteria for surgery. (Schwartz''s Ch. 38)'),
    (v_topic_id, '97: "Primary Hyperaldosteronism" - screen? ', '["Aldosterone/Renin ratio > 20-30", "Both", "None", "None"]', 0, 'Lab screening. (de Virgilio Ch. 17)'),
    (v_topic_id, '98: "MEN 1" - Pancreas? ', '["Gastrinoma (ZES) / Insulinoma", "Both", "None", "None"]', 0, 'Features. (Mont Reid Ch. 11)'),
    (v_topic_id, '99: "MEN 1" - Pituitary? ', '["Prolactinoma #1", "Both", "None", "None"]', 0, 'Features. (Schwartz''s Ch. 38)'),
    (v_topic_id, '100: "Thyroglossal Duct Cyst" - treatment?', '["Sistrunk Procedure (remove cyst + mid-portion of hyoid bone)", "None", "Both", "None"]', 0, 'Pediatric surgery. (de Virgilio Ch. 53)');

    -- Batch 3: 101-350 (Rapid Fire and Special Cases)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: "Triple Negative" breast cancer lacks?', '["ER, PR, and HER2", "Both", "None", "None"]', 0, 'Aggressive biology. (Schwartz''s Ch. 17)'),
